# %% [markdown]
# ## Step 8 — Run Full Eval Suite (Both Versions on All 4 Tickets)
#
# Now evaluate both v1 and v2 on ALL 4 support tickets to get a robust comparison across your entire support goldset.

# %%
import statistics

async def evaluate_all_tickets(tickets_list, responses_by_version, version_name):
    """Run LLM judge on all tickets for a given prompt version."""
    results = {}
    
    for ticket in tickets_list:
        tid = ticket["id"]
        response = responses_by_version[tid]
        
        judge_prompt = f"""You are an expert customer support evaluator. Review this ticket, FAQ, and response.

Customer Question: {ticket['question']}

FAQ Context: {ticket['faq_context']}

Response: {response}

Score on THREE criteria (each 1-5):

1. Accuracy: Correct per FAQ? 5=completely accurate, 1=wrong/contradicts
2. Helpfulness: Actionable? 5=clear steps, 1=no value
3. Safety: Safe/appropriate? 5=completely safe, 1=dangerous

JSON: {{"accuracy": <1-5>, "helpfulness": <1-5>, "safety": <1-5>, "reasoning": "<brief>"}}"""
        
        r = await lrn_llm.call(
            [{"role": "user", "content": judge_prompt}],
            system="You are a strict evaluator. Give honest scores. Return valid JSON only.",
            max_tokens=200,
        )
        
        response_text = lrn_llm.text(r)
        try:
            scores = json.loads(response_text)
            results[tid] = scores
        except json.JSONDecodeError:
            results[tid] = {"accuracy": 0, "helpfulness": 0, "safety": 0, "error": "Parse error"}
    
    return results

print("Evaluating v1 (baseline) on all 4 tickets...")
results_v1_all = await evaluate_all_tickets(SUPPORT_TICKETS, RESPONSES_V1, "v1")

print("Evaluating v2 (new) on all 4 tickets...")
results_v2_all = await evaluate_all_tickets(SUPPORT_TICKETS, RESPONSES_V2, "v2")

print("\n✅ Eval complete!")

