v1_safety = [results_v1_all[tid]["safety"] for tid in results_v1_all if "safety" in results_v1_all[tid]]

v2_accuracy = [results_v2_all[tid]["accuracy"] for tid in results_v2_all if "accuracy" in results_v2_all[tid]]
v2_helpfulness = [results_v2_all[tid]["helpfulness"] for tid in results_v2_all if "helpfulness" in results_v2_all[tid]]
v2_safety = [results_v2_all[tid]["safety"] for tid in results_v2_all if "safety" in results_v2_all[tid]]

print("EVAL COMPARISON REPORT")
print("=" * 70)
print()
print(f"{'Criterion':<20} {'v1 (Baseline)':<18} {'v2 (New)':<18} {'Change'}")
print("-" * 70)

scores_to_compare = []

# Accuracy
if v1_accuracy and v2_accuracy:
    v1_a_mean = statistics.mean(v1_accuracy)
    v2_a_mean = statistics.mean(v2_accuracy)
    diff_a = v2_a_mean - v1_a_mean
    scores_to_compare.append(diff_a)
    print(f"{'Accuracy':<20} {v1_a_mean:.2f}/5{'':<11} {v2_a_mean:.2f}/5{'':<11} {diff_a:+.2f}")

# Helpfulness
if v1_helpfulness and v2_helpfulness:
    v1_h_mean = statistics.mean(v1_helpfulness)
    v2_h_mean = statistics.mean(v2_helpfulness)
    diff_h = v2_h_mean - v1_h_mean
    scores_to_compare.append(diff_h)
    print(f"{'Helpfulness':<20} {v1_h_mean:.2f}/5{'':<11} {v2_h_mean:.2f}/5{'':<11} {diff_h:+.2f}")

# Safety
if v1_safety and v2_safety:
    v1_s_mean = statistics.mean(v1_safety)
    v2_s_mean = statistics.mean(v2_safety)
    diff_s = v2_s_mean - v1_s_mean
    scores_to_compare.append(diff_s)
    print(f"{'Safety':<20} {v1_s_mean:.2f}/5{'':<11} {v2_s_mean:.2f}/5{'':<11} {diff_s:+.2f}")

# Overall
if v1_accuracy and v1_helpfulness and v1_safety and v2_accuracy and v2_helpfulness and v2_safety:
    v1_all = v1_accuracy + v1_helpfulness + v1_safety
    v2_all = v2_accuracy + v2_helpfulness + v2_safety
    v1_overall = statistics.mean(v1_all)
    v2_overall = statistics.mean(v2_all)
    diff_overall = v2_overall - v1_overall
    print("-" * 70)
    print(f"{'OVERALL (all)':<20} {v1_overall:.2f}/5{'':<11} {v2_overall:.2f}/5{'':<11} {diff_overall:+.2f}")

print("\n" + "=" * 70)
print()

# Ship decision
if diff_overall > 0.25:
    decision = "SHIP v2 - Quality improved significantly"
    status = "✅"
elif diff_overall < -0.25:
    decision = "BLOCK v2 - Quality regressed significantly"
    status = "❌"
else:
    decision = "STABLE - v1 and v2 are comparable"
    status = "⏸"

print(f"{status} DECISION: {decision}")

